"use strict";
const pptxgen = require("pptxgenjs");
const path = require("path");

// Colors - Forest & Energy palette (clean, data-forward)
const C = {
  darkBg:    "1A3A2A",   // deep forest green - title/conclusion slides
  lightBg:   "F4F7F5",   // off-white/mint tint - content slides
  primary:   "2C6E49",   // forest green - primary accent
  accent:    "74C69D",   // mint green - secondary accent
  accent2:   "D8F3DC",   // pale green - subtle fills
  highlight:  "F77F00",  // orange - contrast highlight for key stats
  white:     "FFFFFF",
  text:      "1B2E22",   // very dark green for body text
  muted:     "5A7A65",   // muted green for captions
  tableHead: "2C6E49",
  gridLine:  "C8E6D4",
  chartColors: ["2C6E49", "74C69D", "F77F00", "A8DADC"],
  hydro:     "065A82",
  wind:      "2C6E49",
  solar:     "F77F00",
  other:     "A8DADC",
};

const ASSETS = "/app/benchmark/assets";

function makeShadow() {
  return { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.12 };
}

// ─── Helper: Add styled title bar (dark text on light bg slides) ───────────
function addTitle(slide, text, opts = {}) {
  const { y = 0.28, w = 9.0, color = C.text, fontSize = 30 } = opts;
  slide.addText(text, {
    x: 0.5, y, w, h: 0.6,
    fontSize, bold: true, fontFace: "Georgia", color,
    margin: 0, valign: "middle",
  });
}

function addSubtitle(slide, text, opts = {}) {
  const { y = 0.92, w = 9.0, color = C.muted, fontSize = 14 } = opts;
  slide.addText(text, {
    x: 0.5, y, w, h: 0.3,
    fontSize, bold: false, fontFace: "Calibri", color,
    margin: 0, valign: "middle",
  });
}

function addSource(slide, opts = {}) {
  const { color = C.muted, bg = false } = opts;
  slide.addText("Source: Our World in Data – Renewable Energy (Ember 2026; EI Statistical Review 2025)", {
    x: 0.5, y: 5.28, w: 9.0, h: 0.22,
    fontSize: 9, fontFace: "Calibri", color, italic: true, margin: 0,
  });
}

// ─── SLIDE 1: Title ──────────────────────────────────────────────────────────
function slide1(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Large decorative accent shape top-right
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 0, w: 3.0, h: 5.625,
    fill: { color: C.primary }, line: { color: C.primary },
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 8.5, y: 0, w: 1.5, h: 5.625,
    fill: { color: "1E5034" }, line: { color: "1E5034" },
  });

  // Tag line chip
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 0.8, w: 2.4, h: 0.38,
    fill: { color: C.highlight }, line: { color: C.highlight },
  });
  slide.addText("ENERGY TRANSITION", {
    x: 0.5, y: 0.8, w: 2.4, h: 0.38,
    fontSize: 10, bold: true, fontFace: "Calibri", color: C.white,
    align: "center", valign: "middle", margin: 0, charSpacing: 2,
  });

  // Main title
  slide.addText("Global Renewable Energy\nin 2025", {
    x: 0.5, y: 1.35, w: 6.0, h: 1.5,
    fontSize: 38, bold: true, fontFace: "Georgia", color: C.white,
    valign: "top", margin: 0,
  });

  // Subtitle
  slide.addText("How Far Have We Come?", {
    x: 0.5, y: 2.95, w: 6.0, h: 0.5,
    fontSize: 22, bold: false, fontFace: "Georgia", color: C.accent,
    valign: "top", margin: 0, italic: true,
  });

  // Description
  slide.addText("A data-driven overview of renewables' growing share in global energy and electricity — hydropower, wind, and solar.", {
    x: 0.5, y: 3.6, w: 5.8, h: 0.7,
    fontSize: 13, fontFace: "Calibri", color: "B8D4C4",
    valign: "top", margin: 0,
  });

  // Source attribution
  slide.addText("Data: Ember (2026) | Energy Institute Statistical Review of World Energy (2025)\nVia: Our World in Data – ourworldindata.org/renewable-energy\nAuthors: Hannah Ritchie, Max Roser, Pablo Rosado", {
    x: 0.5, y: 4.5, w: 5.8, h: 0.85,
    fontSize: 10, fontFace: "Calibri", color: "7FAF90",
    valign: "top", margin: 0, italic: true,
  });
}

// ─── SLIDE 2: Fossil Fuel Dominance Context ──────────────────────────────────
function slide2(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.18, fill: { color: C.primary }, line: { color: C.primary },
  });

  addTitle(slide, "75% of Global GHG Emissions Still Come from Fossil Fuels");
  addSubtitle(slide, "Setting the context: why the energy transition is urgent");

  // Three stat cards in a row
  const cards = [
    { stat: "75%", label: "of GHG emissions\nfrom fossil fuels", icon: "🌍", color: C.primary },
    { stat: "5M+", label: "premature deaths/yr\nfrom air pollution", icon: "💨", color: "B84040" },
    { stat: "~100%", label: "fossil fuel dominance\nsince Industrial Revolution", icon: "⚙️", color: "5A5A2C" },
  ];

  const cardW = 2.7, cardH = 2.1, cardY = 1.45, gap = 0.25;
  const startX = (10 - (cardW * 3 + gap * 2)) / 2;

  cards.forEach((card, i) => {
    const cx = startX + i * (cardW + gap);
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: cardH,
      fill: { color: C.white }, line: { color: C.gridLine },
      shadow: makeShadow(),
    });
    // Color top bar on card
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: 0.12,
      fill: { color: card.color }, line: { color: card.color },
    });
    // Stat number
    slide.addText(card.stat, {
      x: cx, y: cardY + 0.25, w: cardW, h: 0.7,
      fontSize: 40, bold: true, fontFace: "Georgia", color: card.color,
      align: "center", margin: 0,
    });
    // Label
    slide.addText(card.label, {
      x: cx + 0.1, y: cardY + 1.0, w: cardW - 0.2, h: 0.9,
      fontSize: 13, fontFace: "Calibri", color: C.text,
      align: "center", margin: 0,
    });
  });

  // Body text
  slide.addText([
    { text: "Since the Industrial Revolution, fossil fuels have come to dominate most national energy systems. Burning coal, oil, and gas for energy is the ", options: { breakLine: false } },
    { text: "single largest driver of climate change", options: { bold: true, breakLine: false } },
    { text: " and generates severe local air pollution. Decarbonizing the energy system — through nuclear and renewable technologies — is essential to limiting warming and saving lives.", options: {} },
  ], {
    x: 0.5, y: 3.75, w: 9.0, h: 0.85,
    fontSize: 13, fontFace: "Calibri", color: C.text, margin: 0,
  });

  addSource(slide);
}

// ─── SLIDE 3: Renewables in Primary Energy ──────────────────────────────────
function slide3(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.18, fill: { color: C.primary }, line: { color: C.primary },
  });

  addTitle(slide, "Renewables Now Supply ~14% of Global Primary Energy");
  addSubtitle(slide, "2024 data (substitution method) — primary energy = electricity + transport + heating");

  // Big stat callout left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.3, w: 2.3, h: 2.2,
    fill: { color: C.primary }, line: { color: C.primary },
    shadow: makeShadow(),
  });
  slide.addText("~14%", {
    x: 0.5, y: 1.45, w: 2.3, h: 0.9,
    fontSize: 44, bold: true, fontFace: "Georgia", color: C.white,
    align: "center", margin: 0,
  });
  slide.addText("of global\nprimary energy\nfrom renewables", {
    x: 0.5, y: 2.35, w: 2.3, h: 0.95,
    fontSize: 12, fontFace: "Calibri", color: C.accent,
    align: "center", margin: 0,
  });

  // Key note box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.65, w: 2.3, h: 1.4,
    fill: { color: C.accent2 }, line: { color: C.accent },
  });
  slide.addText("One-seventh\nof all energy\nuse is now\nrenewable", {
    x: 0.5, y: 3.65, w: 2.3, h: 1.4,
    fontSize: 12, fontFace: "Calibri", color: C.primary,
    align: "center", valign: "middle", bold: true, margin: 4,
  });

  // World map image (figure_2.jpg)
  slide.addImage({
    path: path.join(ASSETS, "figure_2.jpg"),
    x: 3.0, y: 1.1, w: 6.7, h: 4.1,
  });

  addSource(slide);
}

// ─── SLIDE 4: Renewable Electricity Generation Growth (Bar Chart) ────────────
function slide4(pres) {
