// ─── SLIDE 2: Fossil Fuel Dominance Context ──────────────────────────────────
function slide2(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.18, fill: { color: C.primary }, line: { color: C.primary },
  });

  addTitle(slide, "75% of Global GHG Emissions Still Come from Fossil Fuels");
  addSubtitle(slide, "Setting the context: why the energy transition is urgent");

  // Three stat cards in a row
  const cards = [
    { stat: "75%", label: "of GHG emissions\nfrom fossil fuels", icon: "🌍", color: C.primary },
    { stat: "5M+", label: "premature deaths/yr\nfrom air pollution", icon: "💨", color: "B84040" },
    { stat: "~100%", label: "fossil fuel dominance\nsince Industrial Revolution", icon: "⚙️", color: "5A5A2C" },
  ];

  const cardW = 2.7, cardH = 2.1, cardY = 1.45, gap = 0.25;
  const startX = (10 - (cardW * 3 + gap * 2)) / 2;

  cards.forEach((card, i) => {
    const cx = startX + i * (cardW + gap);
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: cardH,
      fill: { color: C.white }, line: { color: C.gridLine },
      shadow: makeShadow(),
    });
    // Color top bar on card
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: 0.12,
      fill: { color: card.color }, line: { color: card.color },
    });
    // Stat number
    slide.addText(card.stat, {
      x: cx, y: cardY + 0.25, w: cardW, h: 0.7,
      fontSize: 40, bold: true, fontFace: "Georgia", color: card.color,
      align: "center", margin: 0,
    });
    // Label
    slide.addText(card.label, {
      x: cx + 0.1, y: cardY + 1.0, w: cardW - 0.2, h: 0.9,
      fontSize: 13, fontFace: "Calibri", color: C.text,
      align: "center", margin: 0,
    });
  });

  // Body text
  slide.addText([
    { text: "Since the Industrial Revolution, fossil fuels have come to dominate most national energy systems. Burning coal, oil, and gas for energy is the ", options: { breakLine: false } },
    { text: "single largest driver of climate change", options: { bold: true, breakLine: false } },
    { text: " and generates severe local air pollution. Decarbonizing the energy system — through nuclear and renewable technologies — is essential to limiting warming and saving lives.", options: {} },
  ], {
    x: 0.5, y: 3.75, w: 9.0, h: 0.85,
    fontSize: 13, fontFace: "Calibri", color: C.text, margin: 0,
  });

  addSource(slide);
}

