  // Image caption
  slide.addText("Wind generation by country, 2025 (Our World in Data / Ember)", {
    x: 4.8, y: 4.25, w: 4.9, h: 0.25,
    fontSize: 9, fontFace: "Calibri", color: C.muted, italic: true, margin: 0,
  });

  addSource(slide);
}

// ─── SLIDE 8: Regional Disparities ──────────────────────────────────────────
function slide8(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.18, fill: { color: C.primary }, line: { color: C.primary },
  });

  addTitle(slide, "Stark Regional Gaps: Sub-Saharan Africa Lags While Scandinavia and Latin America Lead");
  addSubtitle(slide, "The energy transition is profoundly uneven — access and investment drive outcomes");

  // Hydro share map (figure_3.jpg)
  slide.addImage({
    path: path.join(ASSETS, "figure_3.jpg"),
    x: 0.4, y: 1.1, w: 5.8, h: 3.55,
  });

  // Two region boxes right
  const regions = [
    {
      label: "Leaders",
      color: C.primary,
      items: [
        "Norway ~98% · Brazil ~85% · Canada ~65%",
        "Denmark & Germany: heavy wind & solar investment",
        "Latin America: abundant hydropower resources",
      ],
    },
    {
      label: "Laggards",
      color: "B84040",
      items: [
        "Saudi Arabia <2% — fossil-fuel-dependent",
        "Sub-Saharan Africa: minimal renewable infrastructure",
        "Much of Middle East below 10%",
      ],
    },
  ];

  regions.forEach((r, i) => {
    const ry = 1.15 + i * 2.05;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.4, y: ry, w: 3.25, h: 1.85,
      fill: { color: C.white }, line: { color: r.color },
      shadow: makeShadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.4, y: ry, w: 3.25, h: 0.35,
      fill: { color: r.color }, line: { color: r.color },
    });
    slide.addText(r.label, {
      x: 6.45, y: ry, w: 3.15, h: 0.35,
      fontSize: 13, bold: true, fontFace: "Georgia", color: C.white,
      valign: "middle", margin: 0,
    });
    r.items.forEach((item, j) => {
      slide.addText("→  " + item, {
        x: 6.48, y: ry + 0.4 + j * 0.42, w: 3.1, h: 0.38,
        fontSize: 10.5, fontFace: "Calibri", color: C.text,
        margin: 0,
      });
    });
  });

  // Image caption
  slide.addText("Share of electricity from hydropower by country, 2025 (Our World in Data / Ember)", {
    x: 0.4, y: 4.7, w: 5.8, h: 0.22,
    fontSize: 9, fontFace: "Calibri", color: C.muted, italic: true, margin: 0,
  });

  addSource(slide);
}

// ─── SLIDE 9: Key Takeaways ───────────────────────────────────────────────────
function slide9(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Accent shape top-right
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 8.0, y: 0, w: 2.0, h: 5.625,
    fill: { color: C.primary }, line: { color: C.primary },
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 8.8, y: 0, w: 1.2, h: 5.625,
    fill: { color: "1E5034" }, line: { color: "1E5034" },
  });

  // Section chip
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 0.35, w: 2.6, h: 0.32,
    fill: { color: C.highlight }, line: { color: C.highlight },
  });
  slide.addText("KEY TAKEAWAYS", {
    x: 0.5, y: 0.35, w: 2.6, h: 0.32,
    fontSize: 10, bold: true, fontFace: "Calibri", color: C.white,
    align: "center", valign: "middle", margin: 0, charSpacing: 2,
  });

  addTitle(slide, "Renewables Are Growing Fast —\nBut the Transition Must Accelerate", { y: 0.75, color: C.white, fontSize: 26 });

  const takeaways = [
    { num: "01", text: "~14% of global primary energy and ~30% of global electricity now come from renewables — significant milestones, but well short of climate targets." },
    { num: "02", text: "Hydropower dominates renewable electricity (~47%) but has limited growth potential; wind and solar are the growth engines." },
    { num: "03", text: "Wind (~2,400 TWh) and solar (~2,000 TWh) combined now nearly match hydro output and are the fastest-growing energy technologies in history." },
    { num: "04", text: "Stark regional gaps persist: Scandinavia and Latin America lead at 65–98%; Sub-Saharan Africa and the Middle East remain below 10%." },
    { num: "05", text: "Transport and heating lag far behind electricity in decarbonization, keeping the overall primary energy share much lower than the electricity share." },
  ];

  takeaways.forEach((t, i) => {
    const ty = 1.6 + i * 0.75;
    // Number badge
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: ty, w: 0.38, h: 0.55,
      fill: { color: C.highlight }, line: { color: C.highlight },
    });
    slide.addText(t.num, {
      x: 0.5, y: ty, w: 0.38, h: 0.55,
      fontSize: 12, bold: true, fontFace: "Calibri", color: C.white,
      align: "center", valign: "middle", margin: 0,
    });
    // Text
    slide.addText(t.text, {
      x: 1.02, y: ty + 0.04, w: 6.7, h: 0.5,
      fontSize: 12, fontFace: "Calibri", color: "D4EAD8",
      margin: 0,
    });
  });

  // Closing call to action
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.2, w: 7.2, h: 0.28,
    fill: { color: C.primary }, line: { color: C.primary },
  });
  slide.addText("The window to meet 1.5°C targets is narrowing — scaling wind and solar must be the top global energy priority.", {
    x: 0.5, y: 5.2, w: 7.2, h: 0.28,
    fontSize: 10.5, fontFace: "Calibri", color: C.white,
    align: "center", valign: "middle", margin: 0, italic: true,
  });
}

// ─── BUILD PRESENTATION ──────────────────────────────────────────────────────
async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.title = "Global Renewable Energy in 2025: How Far Have We Come?";
  pres.author = "Our World in Data";
  pres.subject = "Global Renewable Energy Trends";

  slide1(pres);
  slide2(pres);
  slide3(pres);
  slide4(pres);
  slide5(pres);
  slide6(pres);
  slide7(pres);
  slide8(pres);
  slide9(pres);

  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Done: /app/output/final_deck.pptx");
}

main().catch(e => { console.error(e); process.exit(1); });

