"use strict";
const pptxgen = require("pptxgenjs");
const path = require("path");

// Colors - Forest & Energy palette (clean, data-forward)
const C = {
  darkBg:    "1A3A2A",   // deep forest green - title/conclusion slides
  lightBg:   "F4F7F5",   // off-white/mint tint - content slides
  primary:   "2C6E49",   // forest green - primary accent
  accent:    "74C69D",   // mint green - secondary accent
  accent2:   "D8F3DC",   // pale green - subtle fills
  highlight:  "F77F00",  // orange - contrast highlight for key stats
  white:     "FFFFFF",
  text:      "1B2E22",   // very dark green for body text
  muted:     "5A7A65",   // muted green for captions
  tableHead: "2C6E49",
  gridLine:  "C8E6D4",
  chartColors: ["2C6E49", "74C69D", "F77F00", "A8DADC"],
  hydro:     "065A82",
  wind:      "2C6E49",
  solar:     "F77F00",
  other:     "A8DADC",
};

const ASSETS = "/app/benchmark/assets";

function makeShadow() {
  return { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.12 };
}

// ─── Helper: Add styled title bar (dark text on light bg slides) ───────────
function addTitle(slide, text, opts = {}) {
  const { y = 0.28, w = 9.0, color = C.text, fontSize = 30 } = opts;
  slide.addText(text, {
    x: 0.5, y, w, h: 0.6,
    fontSize, bold: true, fontFace: "Georgia", color,
    margin: 0, valign: "middle",
  });
}

function addSubtitle(slide, text, opts = {}) {
  const { y = 0.92, w = 9.0, color = C.muted, fontSize = 14 } = opts;
  slide.addText(text, {
    x: 0.5, y, w, h: 0.3,
    fontSize, bold: false, fontFace: "Calibri", color,
    margin: 0, valign: "middle",
  });
}

function addSource(slide, opts = {}) {
  const { color = C.muted, bg = false } = opts;
  slide.addText("Source: Our World in Data – Renewable Energy (Ember 2026; EI Statistical Review 2025)", {
    x: 0.5, y: 5.28, w: 9.0, h: 0.22,
    fontSize: 9, fontFace: "Calibri", color, italic: true, margin: 0,
  });
}

// ─── SLIDE 1: Title ──────────────────────────────────────────────────────────
function slide1(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Large decorative accent shape top-right
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 0, w: 3.0, h: 5.625,
    fill: { color: C.primary }, line: { color: C.primary },
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 8.5, y: 0, w: 1.5, h: 5.625,
    fill: { color: "1E5034" }, line: { color: "1E5034" },
  });

  // Tag line chip
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 0.8, w: 2.4, h: 0.38,
    fill: { color: C.highlight }, line: { color: C.highlight },
  });
  slide.addText("ENERGY TRANSITION", {
    x: 0.5, y: 0.8, w: 2.4, h: 0.38,
    fontSize: 10, bold: true, fontFace: "Calibri", color: C.white,
    align: "center", valign: "middle", margin: 0, charSpacing: 2,
  });

  // Main title
  slide.addText("Global Renewable Energy\nin 2025", {
    x: 0.5, y: 1.35, w: 6.0, h: 1.5,
    fontSize: 38, bold: true, fontFace: "Georgia", color: C.white,
    valign: "top", margin: 0,
  });

  // Subtitle
  slide.addText("How Far Have We Come?", {
    x: 0.5, y: 2.95, w: 6.0, h: 0.5,
    fontSize: 22, bold: false, fontFace: "Georgia", color: C.accent,
    valign: "top", margin: 0, italic: true,
  });

  // Description
  slide.addText("A data-driven overview of renewables' growing share in global energy and electricity — hydropower, wind, and solar.", {
    x: 0.5, y: 3.6, w: 5.8, h: 0.7,
    fontSize: 13, fontFace: "Calibri", color: "B8D4C4",
    valign: "top", margin: 0,
  });

  // Source attribution
  slide.addText("Data: Ember (2026) | Energy Institute Statistical Review of World Energy (2025)\nVia: Our World in Data – ourworldindata.org/renewable-energy\nAuthors: Hannah Ritchie, Max Roser, Pablo Rosado", {
    x: 0.5, y: 4.5, w: 5.8, h: 0.85,
    fontSize: 10, fontFace: "Calibri", color: "7FAF90",
    valign: "top", margin: 0, italic: true,
  });
}

// ─── SLIDE 2: Fossil Fuel Dominance Context ──────────────────────────────────
function slide2(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.18, fill: { color: C.primary }, line: { color: C.primary },
  });

  addTitle(slide, "75% of Global GHG Emissions Still Come from Fossil Fuels");
  addSubtitle(slide, "Setting the context: why the energy transition is urgent");

  // Three stat cards in a row
  const cards = [
    { stat: "75%", label: "of GHG emissions\nfrom fossil fuels", icon: "🌍", color: C.primary },
    { stat: "5M+", label: "premature deaths/yr\nfrom air pollution", icon: "💨", color: "B84040" },
    { stat: "~100%", label: "fossil fuel dominance\nsince Industrial Revolution", icon: "⚙️", color: "5A5A2C" },
  ];

  const cardW = 2.7, cardH = 2.1, cardY = 1.45, gap = 0.25;
  const startX = (10 - (cardW * 3 + gap * 2)) / 2;

  cards.forEach((card, i) => {
    const cx = startX + i * (cardW + gap);
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: cardH,
      fill: { color: C.white }, line: { color: C.gridLine },
      shadow: makeShadow(),
    });
    // Color top bar on card
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: 0.12,
      fill: { color: card.color }, line: { color: card.color },
    });
    // Stat number
    slide.addText(card.stat, {
      x: cx, y: cardY + 0.25, w: cardW, h: 0.7,
      fontSize: 40, bold: true, fontFace: "Georgia", color: card.color,
      align: "center", margin: 0,
    });
    // Label
    slide.addText(card.label, {
      x: cx + 0.1, y: cardY + 1.0, w: cardW - 0.2, h: 0.9,
      fontSize: 13, fontFace: "Calibri", color: C.text,
      align: "center", margin: 0,
    });
  });

  // Body text
  slide.addText([
    { text: "Since the Industrial Revolution, fossil fuels have come to dominate most national energy systems. Burning coal, oil, and gas for energy is the ", options: { breakLine: false } },
    { text: "single largest driver of climate change", options: { bold: true, breakLine: false } },
    { text: " and generates severe local air pollution. Decarbonizing the energy system — through nuclear and renewable technologies — is essential to limiting warming and saving lives.", options: {} },
  ], {
    x: 0.5, y: 3.75, w: 9.0, h: 0.85,
    fontSize: 13, fontFace: "Calibri", color: C.text, margin: 0,
  });

  addSource(slide);
}

// ─── SLIDE 3: Renewables in Primary Energy ──────────────────────────────────
function slide3(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.18, fill: { color: C.primary }, line: { color: C.primary },
  });

  addTitle(slide, "Renewables Now Supply ~14% of Global Primary Energy");
  addSubtitle(slide, "2024 data (substitution method) — primary energy = electricity + transport + heating");

  // Big stat callout left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.3, w: 2.3, h: 2.2,
    fill: { color: C.primary }, line: { color: C.primary },
    shadow: makeShadow(),
  });
  slide.addText("~14%", {
    x: 0.5, y: 1.45, w: 2.3, h: 0.9,
    fontSize: 44, bold: true, fontFace: "Georgia", color: C.white,
    align: "center", margin: 0,
  });
  slide.addText("of global\nprimary energy\nfrom renewables", {
    x: 0.5, y: 2.35, w: 2.3, h: 0.95,
    fontSize: 12, fontFace: "Calibri", color: C.accent,
    align: "center", margin: 0,
  });

  // Key note box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.65, w: 2.3, h: 1.4,
    fill: { color: C.accent2 }, line: { color: C.accent },
  });
  slide.addText("One-seventh\nof all energy\nuse is now\nrenewable", {
    x: 0.5, y: 3.65, w: 2.3, h: 1.4,
    fontSize: 12, fontFace: "Calibri", color: C.primary,
    align: "center", valign: "middle", bold: true, margin: 4,
  });

  // World map image (figure_2.jpg)
  slide.addImage({
    path: path.join(ASSETS, "figure_2.jpg"),
    x: 3.0, y: 1.1, w: 6.7, h: 4.1,
  });

  addSource(slide);
}

// ─── SLIDE 4: Renewable Electricity Generation Growth (Bar Chart) ────────────
function slide4(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.18, fill: { color: C.primary }, line: { color: C.primary },
  });

  addTitle(slide, "Renewable Electricity Generation: ~9,600 TWh Total in 2024");
  addSubtitle(slide, "Hydropower leads — but wind and solar are growing fastest");

  // Bar chart left
  const chartData = [{
    name: "Generation (TWh)",
    labels: ["Hydropower", "Wind", "Solar", "Other Renewables"],
    values: [4500, 2400, 2000, 700],
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.4, y: 1.15, w: 5.3, h: 3.85,
    barDir: "bar",
    chartColors: [C.hydro, C.wind, C.solar, "A8DADC"],
    chartArea: { fill: { color: C.lightBg }, roundedCorners: false },
    catAxisLabelColor: C.text,
    valAxisLabelColor: C.muted,
    valGridLine: { color: C.gridLine, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelColor: "FFFFFF",
    dataLabelFontSize: 11,
    dataLabelFontBold: true,
    showLegend: false,
  });

  // Data table right
  const tableData = [
    [
      { text: "Technology", options: { fill: { color: C.tableHead }, color: C.white, bold: true, fontSize: 11 } },
      { text: "TWh (2024)", options: { fill: { color: C.tableHead }, color: C.white, bold: true, fontSize: 11 } },
      { text: "% of Renewables", options: { fill: { color: C.tableHead }, color: C.white, bold: true, fontSize: 11 } },
    ],
    [
      { text: "Hydropower", options: { color: C.text, fontSize: 11 } },
      { text: "~4,500", options: { color: C.text, fontSize: 11, bold: true } },
      { text: "~47%", options: { color: C.text, fontSize: 11 } },
    ],
    [
      { text: "Wind", options: { color: C.text, fontSize: 11 } },
      { text: "~2,400", options: { color: C.text, fontSize: 11, bold: true } },
      { text: "~25%", options: { color: C.text, fontSize: 11 } },
    ],
    [
      { text: "Solar", options: { color: C.text, fontSize: 11 } },
      { text: "~2,000", options: { color: C.text, fontSize: 11, bold: true } },
      { text: "~21%", options: { color: C.text, fontSize: 11 } },
    ],
    [
      { text: "Other (geo, biomass, etc.)", options: { color: C.text, fontSize: 11 } },
      { text: "~700", options: { color: C.text, fontSize: 11, bold: true } },
      { text: "~7%", options: { color: C.text, fontSize: 11 } },
    ],
  ];

  slide.addTable(tableData, {
    x: 5.9, y: 1.15, w: 3.8, h: 2.4,
    border: { pt: 0.5, color: C.gridLine },
    colW: [1.9, 1.0, 0.9],
    rowH: 0.44,
  });

  // Key insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.9, y: 3.75, w: 3.8, h: 1.25,
    fill: { color: C.accent2 }, line: { color: C.accent },
  });
  slide.addText("Wind + Solar combined\n(~4,400 TWh) now nearly\nmatch Hydropower's output\nand are growing far faster.", {
    x: 5.9, y: 3.75, w: 3.8, h: 1.25,
    fontSize: 11.5, fontFace: "Calibri", color: C.primary,
    align: "center", valign: "middle", bold: false, margin: 6,
  });

  addSource(slide);
}

// ─── SLIDE 5: Electricity Mix One-Third Renewable ────────────────────────────
function slide5(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.18, fill: { color: C.primary }, line: { color: C.primary },
  });

  addTitle(slide, "Almost One-Third of Global Electricity Now Comes from Renewables");
  addSubtitle(slide, "2025 data — electricity sector leads all energy sectors in renewable deployment");

  // World map (figure_1.jpg) - left half
  slide.addImage({
    path: path.join(ASSETS, "figure_1.jpg"),
    x: 0.4, y: 1.1, w: 5.8, h: 3.7,
  });

  // Country data table - right
  const tableData = [
    [
      { text: "Country / Region", options: { fill: { color: C.tableHead }, color: C.white, bold: true, fontSize: 10 } },
      { text: "Renewables Share", options: { fill: { color: C.tableHead }, color: C.white, bold: true, fontSize: 10 } },
    ],
    [{ text: "Norway", options: { color: C.text, fontSize: 10 } }, { text: "~98%", options: { color: "065A82", bold: true, fontSize: 10 } }],
    [{ text: "Brazil", options: { color: C.text, fontSize: 10 } }, { text: "~85%", options: { color: "065A82", bold: true, fontSize: 10 } }],
    [{ text: "Canada", options: { color: C.text, fontSize: 10 } }, { text: "~65%", options: { color: C.primary, bold: true, fontSize: 10 } }],
    [{ text: "China", options: { color: C.text, fontSize: 10 } }, { text: "~35%", options: { color: C.primary, bold: true, fontSize: 10 } }],
    [{ text: "India", options: { color: C.text, fontSize: 10 } }, { text: "~25%", options: { color: C.muted, bold: true, fontSize: 10 } }],
    [{ text: "Saudi Arabia", options: { color: C.text, fontSize: 10 } }, { text: "<2%", options: { color: "B84040", bold: true, fontSize: 10 } }],
    [{ text: "World Average", options: { color: C.text, bold: true, fontSize: 10 } }, { text: "~30%", options: { color: C.highlight, bold: true, fontSize: 10 } }],
  ];

  slide.addTable(tableData, {
    x: 6.4, y: 1.15, w: 3.2, h: 3.0,
    border: { pt: 0.5, color: C.gridLine },
    colW: [1.8, 1.4],
    rowH: 0.36,
  });

  // Key stat callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.4, y: 4.3, w: 3.2, h: 0.85,
    fill: { color: C.primary }, line: { color: C.primary },
  });
  slide.addText("~30% global avg · Many African/\nMiddle Eastern nations below 10%", {
    x: 6.4, y: 4.3, w: 3.2, h: 0.85,
    fontSize: 11, fontFace: "Calibri", color: C.white,
    align: "center", valign: "middle", margin: 4,
  });

  addSource(slide);
}

// ─── SLIDE 6: Hydropower Largest Source ─────────────────────────────────────
function slide6(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.18, fill: { color: "065A82" }, line: { color: "065A82" },
  });

  addTitle(slide, "Hydropower Remains the Largest Renewable Source at ~50% of Generation");
  addSubtitle(slide, "Over a century of scale — China, Brazil, and Canada are top producers");

  // Hydro map (figure_6.jpg)
  slide.addImage({
    path: path.join(ASSETS, "figure_6.jpg"),
    x: 0.4, y: 1.1, w: 6.0, h: 3.8,
  });

  // Stat cards right
  const facts = [
    { val: "~4,500 TWh", desc: "global hydro generation (2024)" },
    { val: "~47%", desc: "of all renewable electricity" },
    { val: "3 leaders", desc: "China · Brazil · Canada" },
    { val: "100+ yrs", desc: "of large-scale hydro operation" },
  ];

  facts.forEach((f, i) => {
    const fy = 1.15 + i * 1.08;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.65, y: fy, w: 3.0, h: 0.92,
      fill: { color: C.white }, line: { color: C.gridLine },
      shadow: makeShadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.65, y: fy, w: 0.07, h: 0.92,
      fill: { color: "065A82" }, line: { color: "065A82" },
    });
    slide.addText(f.val, {
      x: 6.78, y: fy + 0.05, w: 2.82, h: 0.36,
      fontSize: 16, bold: true, fontFace: "Georgia", color: "065A82",
      margin: 0,
    });
    slide.addText(f.desc, {
      x: 6.78, y: fy + 0.43, w: 2.82, h: 0.36,
      fontSize: 11, fontFace: "Calibri", color: C.muted,
      margin: 0,
    });
  });

  // Footnote
  slide.addText("Hydro growth is limited by geography and environmental constraints — wind and solar have greater untapped potential.", {
    x: 0.5, y: 5.1, w: 6.0, h: 0.35,
    fontSize: 10, fontFace: "Calibri", color: C.muted, italic: true, margin: 0,
  });

  addSource(slide);
}

// ─── SLIDE 7: Wind and Solar Fastest Growing ────────────────────────────────
function slide7(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.18, fill: { color: C.primary }, line: { color: C.primary },
  });

  addTitle(slide, "Wind and Solar Are the Fastest-Growing Energy Technologies in History");
  addSubtitle(slide, "Together ~4,400 TWh — now nearly matching hydropower's 4,500 TWh output");

  // Wind map (figure_8.jpg) - right column
  slide.addImage({
    path: path.join(ASSETS, "figure_8.jpg"),
    x: 4.8, y: 1.1, w: 4.9, h: 3.1,
  });

  // Wind vs Solar comparison cards left
  const cmpCards = [
    {
      label: "Wind", twh: "~2,400 TWh", share: "~25% of renewable electricity",
      note: "Onshore + offshore; strong in Europe, China, USA",
      color: C.wind,
    },
    {
      label: "Solar", twh: "~2,000 TWh", share: "~21% of renewable electricity",
      note: "Fastest-growing source; dramatic rise since 2010 — driven by cost declines & policy",
      color: C.solar,
    },
  ];

  cmpCards.forEach((c, i) => {
    const cy = 1.18 + i * 1.6;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.4, y: cy, w: 4.0, h: 1.35,
      fill: { color: C.white }, line: { color: C.gridLine },
      shadow: makeShadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.4, y: cy, w: 4.0, h: 0.14,
      fill: { color: c.color }, line: { color: c.color },
    });
    slide.addText(c.label + "  ·  " + c.twh, {
      x: 0.55, y: cy + 0.18, w: 3.8, h: 0.38,
      fontSize: 18, bold: true, fontFace: "Georgia", color: c.color,
      margin: 0,
    });
    slide.addText(c.share, {
      x: 0.55, y: cy + 0.57, w: 3.8, h: 0.26,
      fontSize: 12, fontFace: "Calibri", color: C.text,
      margin: 0,
    });
    slide.addText(c.note, {
      x: 0.55, y: cy + 0.84, w: 3.8, h: 0.36,
      fontSize: 10, fontFace: "Calibri", color: C.muted,
      margin: 0, italic: true,
    });
  });

  // Combined callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 4.38, w: 4.0, h: 0.9,
    fill: { color: C.accent2 }, line: { color: C.accent },
  });
  slide.addText("Wind + Solar Combined: ~4,400 TWh ≈ Hydro (~4,500 TWh)\nBut growing far faster — no geographic ceiling", {
    x: 0.4, y: 4.38, w: 4.0, h: 0.9,
    fontSize: 11.5, fontFace: "Calibri", color: C.primary,
    align: "center", valign: "middle", bold: true, margin: 4,
  });

  // Image caption
  slide.addText("Wind generation by country, 2025 (Our World in Data / Ember)", {
    x: 4.8, y: 4.25, w: 4.9, h: 0.25,
    fontSize: 9, fontFace: "Calibri", color: C.muted, italic: true, margin: 0,
  });

  addSource(slide);
}

// ─── SLIDE 8: Regional Disparities ──────────────────────────────────────────
function slide8(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.18, fill: { color: C.primary }, line: { color: C.primary },
  });

  addTitle(slide, "Stark Regional Gaps: Sub-Saharan Africa Lags While Scandinavia and Latin America Lead");
  addSubtitle(slide, "The energy transition is profoundly uneven — access and investment drive outcomes");

  // Hydro share map (figure_3.jpg)
  slide.addImage({
    path: path.join(ASSETS, "figure_3.jpg"),
    x: 0.4, y: 1.1, w: 5.8, h: 3.55,
  });

  // Two region boxes right
  const regions = [
    {
      label: "Leaders",
      color: C.primary,
      items: [
        "Norway ~98% · Brazil ~85% · Canada ~65%",
        "Denmark & Germany: heavy wind & solar investment",
        "Latin America: abundant hydropower resources",
      ],
    },
    {
      label: "Laggards",
      color: "B84040",
      items: [
        "Saudi Arabia <2% — fossil-fuel-dependent",
        "Sub-Saharan Africa: minimal renewable infrastructure",
        "Much of Middle East below 10%",
      ],
    },
  ];

  regions.forEach((r, i) => {
    const ry = 1.15 + i * 2.05;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.4, y: ry, w: 3.25, h: 1.85,
      fill: { color: C.white }, line: { color: r.color },
      shadow: makeShadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.4, y: ry, w: 3.25, h: 0.35,
      fill: { color: r.color }, line: { color: r.color },
    });
    slide.addText(r.label, {
      x: 6.45, y: ry, w: 3.15, h: 0.35,
      fontSize: 13, bold: true, fontFace: "Georgia", color: C.white,
      valign: "middle", margin: 0,
    });
    r.items.forEach((item, j) => {
      slide.addText("→  " + item, {
        x: 6.48, y: ry + 0.4 + j * 0.42, w: 3.1, h: 0.38,
        fontSize: 10.5, fontFace: "Calibri", color: C.text,
        margin: 0,
      });
    });
  });

  // Image caption
  slide.addText("Share of electricity from hydropower by country, 2025 (Our World in Data / Ember)", {
    x: 0.4, y: 4.7, w: 5.8, h: 0.22,
    fontSize: 9, fontFace: "Calibri", color: C.muted, italic: true, margin: 0,
  });

  addSource(slide);
}

// ─── SLIDE 9: Key Takeaways ───────────────────────────────────────────────────
function slide9(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Accent shape top-right
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 8.0, y: 0, w: 2.0, h: 5.625,
    fill: { color: C.primary }, line: { color: C.primary },
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 8.8, y: 0, w: 1.2, h: 5.625,
    fill: { color: "1E5034" }, line: { color: "1E5034" },
  });

  // Section chip
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 0.35, w: 2.6, h: 0.32,
    fill: { color: C.highlight }, line: { color: C.highlight },
  });
  slide.addText("KEY TAKEAWAYS", {
    x: 0.5, y: 0.35, w: 2.6, h: 0.32,
    fontSize: 10, bold: true, fontFace: "Calibri", color: C.white,
    align: "center", valign: "middle", margin: 0, charSpacing: 2,
  });

  addTitle(slide, "Renewables Are Growing Fast —\nBut the Transition Must Accelerate", { y: 0.75, color: C.white, fontSize: 26 });

  const takeaways = [
    { num: "01", text: "~14% of global primary energy and ~30% of global electricity now come from renewables — significant milestones, but well short of climate targets." },
    { num: "02", text: "Hydropower dominates renewable electricity (~47%) but has limited growth potential; wind and solar are the growth engines." },
    { num: "03", text: "Wind (~2,400 TWh) and solar (~2,000 TWh) combined now nearly match hydro output and are the fastest-growing energy technologies in history." },
    { num: "04", text: "Stark regional gaps persist: Scandinavia and Latin America lead at 65–98%; Sub-Saharan Africa and the Middle East remain below 10%." },
    { num: "05", text: "Transport and heating lag far behind electricity in decarbonization, keeping the overall primary energy share much lower than the electricity share." },
  ];

  takeaways.forEach((t, i) => {
    const ty = 1.6 + i * 0.75;
    // Number badge
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: ty, w: 0.38, h: 0.55,
      fill: { color: C.highlight }, line: { color: C.highlight },
    });
    slide.addText(t.num, {
      x: 0.5, y: ty, w: 0.38, h: 0.55,
      fontSize: 12, bold: true, fontFace: "Calibri", color: C.white,
      align: "center", valign: "middle", margin: 0,
    });
    // Text
    slide.addText(t.text, {
      x: 1.02, y: ty + 0.04, w: 6.7, h: 0.5,
      fontSize: 12, fontFace: "Calibri", color: "D4EAD8",
      margin: 0,
    });
  });

  // Closing call to action
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.2, w: 7.2, h: 0.28,
    fill: { color: C.primary }, line: { color: C.primary },
  });
  slide.addText("The window to meet 1.5°C targets is narrowing — scaling wind and solar must be the top global energy priority.", {
    x: 0.5, y: 5.2, w: 7.2, h: 0.28,
    fontSize: 10.5, fontFace: "Calibri", color: C.white,
    align: "center", valign: "middle", margin: 0, italic: true,
  });
}

// ─── BUILD PRESENTATION ──────────────────────────────────────────────────────
async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.title = "Global Renewable Energy in 2025: How Far Have We Come?";
  pres.author = "Our World in Data";
  pres.subject = "Global Renewable Energy Trends";

  slide1(pres);
  slide2(pres);
  slide3(pres);
  slide4(pres);
  slide5(pres);
  slide6(pres);
  slide7(pres);
  slide8(pres);
  slide9(pres);

  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Done: /app/output/final_deck.pptx");
}

main().catch(e => { console.error(e); process.exit(1); });

