  addSubtitle(slide, "2024 data (substitution method) — primary energy = electricity + transport + heating");

  // Big stat callout left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.3, w: 2.3, h: 2.2,
    fill: { color: C.primary }, line: { color: C.primary },
    shadow: makeShadow(),
