      { text: "~47%", options: { color: C.text, fontSize: 11 } },
    ],
    [
      { text: "Wind", options: { color: C.text, fontSize: 11 } },
      { text: "~2,400", options: { color: C.text, fontSize: 11, bold: true } },
      { text: "~25%", options: { color: C.text, fontSize: 11 } },
    ],
    [
      { text: "Solar", options: { color: C.text, fontSize: 11 } },
      { text: "~2,000", options: { color: C.text, fontSize: 11, bold: true } },
      { text: "~21%", options: { color: C.text, fontSize: 11 } },
