  slide.addText("Wind + Solar combined\n(~4,400 TWh) now nearly\nmatch Hydropower's output\nand are growing far faster.", {
    x: 5.9, y: 3.75, w: 3.8, h: 1.25,
    fontSize: 11.5, fontFace: "Calibri", color: C.primary,
    align: "center", valign: "middle", bold: false, margin: 6,
