// ─── SLIDE 7: Wind and Solar Fastest Growing ────────────────────────────────
function slide7(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.18, fill: { color: C.primary }, line: { color: C.primary },
  });

  addTitle(slide, "Wind and Solar Are the Fastest-Growing Energy Technologies in History");
  addSubtitle(slide, "Together ~4,400 TWh — now nearly matching hydropower's 4,500 TWh output");

  // Wind map (figure_8.jpg) - right column
  slide.addImage({
    path: path.join(ASSETS, "figure_8.jpg"),
    x: 4.8, y: 1.1, w: 4.9, h: 3.1,
  });

  // Wind vs Solar comparison cards left
  const cmpCards = [
    {
      label: "Wind", twh: "~2,400 TWh", share: "~25% of renewable electricity",
      note: "Onshore + offshore; strong in Europe, China, USA",
      color: C.wind,
    },
    {
      label: "Solar", twh: "~2,000 TWh", share: "~21% of renewable electricity",
      note: "Fastest-growing source; dramatic rise since 2010 — driven by cost declines & policy",
      color: C.solar,
    },
  ];

  cmpCards.forEach((c, i) => {
    const cy = 1.18 + i * 1.6;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.4, y: cy, w: 4.0, h: 1.35,
      fill: { color: C.white }, line: { color: C.gridLine },
      shadow: makeShadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.4, y: cy, w: 4.0, h: 0.14,
      fill: { color: c.color }, line: { color: c.color },
    });
    slide.addText(c.label + "  ·  " + c.twh, {
      x: 0.55, y: cy + 0.18, w: 3.8, h: 0.38,
      fontSize: 18, bold: true, fontFace: "Georgia", color: c.color,
      margin: 0,
    });
    slide.addText(c.share, {
      x: 0.55, y: cy + 0.57, w: 3.8, h: 0.26,
      fontSize: 12, fontFace: "Calibri", color: C.text,
      margin: 0,
    });
    slide.addText(c.note, {
      x: 0.55, y: cy + 0.84, w: 3.8, h: 0.36,
      fontSize: 10, fontFace: "Calibri", color: C.muted,
      margin: 0, italic: true,
    });
  });

  // Combined callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 4.38, w: 4.0, h: 0.9,
    fill: { color: C.accent2 }, line: { color: C.accent },
  });
  slide.addText("Wind + Solar Combined: ~4,400 TWh ≈ Hydro (~4,500 TWh)\nBut growing far faster — no geographic ceiling", {
    x: 0.4, y: 4.38, w: 4.0, h: 0.9,
    fontSize: 11.5, fontFace: "Calibri", color: C.primary,
    align: "center", valign: "middle", bold: true, margin: 4,
  });

  // Image caption
  slide.addText("Wind generation by country, 2025 (Our World in Data / Ember)", {
    x: 4.8, y: 4.25, w: 4.9, h: 0.25,
    fontSize: 9, fontFace: "Calibri", color: C.muted, italic: true, margin: 0,
  });

  addSource(slide);
}

// ─── SLIDE 8: Regional Disparities ──────────────────────────────────────────
function slide8(pres) {
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.18, fill: { color: C.primary }, line: { color: C.primary },
  });

  addTitle(slide, "Stark Regional Gaps: Sub-Saharan Africa Lags While Scandinavia and Latin America Lead");
  addSubtitle(slide, "The energy transition is profoundly uneven — access and investment drive outcomes");

  // Hydro share map (figure_3.jpg)
  slide.addImage({
    path: path.join(ASSETS, "figure_3.jpg"),
    x: 0.4, y: 1.1, w: 5.8, h: 3.55,
  });

  // Two region boxes right
  const regions = [
    {
      label: "Leaders",
      color: C.primary,
      items: [
        "Norway ~98% · Brazil ~85% · Canada ~65%",
        "Denmark & Germany: heavy wind & solar investment",
        "Latin America: abundant hydropower resources",
      ],
    },
    {
      label: "Laggards",
      color: "B84040",
      items: [
        "Saudi Arabia <2% — fossil-fuel-dependent",
        "Sub-Saharan Africa: minimal renewable infrastructure",
        "Much of Middle East below 10%",
      ],
    },
  ];

  regions.forEach((r, i) => {
    const ry = 1.15 + i * 2.05;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.4, y: ry, w: 3.25, h: 1.85,
      fill: { color: C.white }, line: { color: r.color },
      shadow: makeShadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.4, y: ry, w: 3.25, h: 0.35,
      fill: { color: r.color }, line: { color: r.color },
    });
    slide.addText(r.label, {
      x: 6.45, y: ry, w: 3.15, h: 0.35,
      fontSize: 13, bold: true, fontFace: "Georgia", color: C.white,
      valign: "middle", margin: 0,
    });
    r.items.forEach((item, j) => {
      slide.addText("→  " + item, {
        x: 6.48, y: ry + 0.4 + j * 0.42, w: 3.1, h: 0.38,
        fontSize: 10.5, fontFace: "Calibri", color: C.text,
        margin: 0,
      });
    });
  });

  // Image caption
  slide.addText("Share of electricity from hydropower by country, 2025 (Our World in Data / Ember)", {
    x: 0.4, y: 4.7, w: 5.8, h: 0.22,
    fontSize: 9, fontFace: "Calibri", color: C.muted, italic: true, margin: 0,
  });

  addSource(slide);
}

